#include "AuditIntegrityEngine.h"
#include <iostream>
#include <fstream>
#include <sstream>
#include <iomanip>
#include <vector>
#include <cstdint>
using namespace std;
namespace {
const vector<string> tracked={"users.txt","resources.txt","security_logs.txt","incidents.txt","permissions.txt","policies.txt","security_cases.txt","alerts.txt"};
string hashFile(const string& name,bool& exists){ifstream in(name,ios::binary);if(!in){exists=false;return "MISSING";}exists=true;uint64_t h=1469598103934665603ULL;char c;while(in.get(c)){h^=static_cast<unsigned char>(c);h*=1099511628211ULL;}stringstream ss;ss<<hex<<uppercase<<h;return ss.str();}
}
AuditIntegrityEngine::AuditIntegrityEngine(SecurityLogger& securityLogger):logger(securityLogger){}
void AuditIntegrityEngine::createBaseline(const string& actor,const string& role){ofstream out("integrity_baseline.txt",ios::trunc);if(!out){cout<<"Could not write baseline.\n";return;}out<<"VIGILX LOCAL FILE INTEGRITY BASELINE\n"<<"Algorithm: FNV-1a 64-bit (educational change-detection checksum, not cryptographic).\n";for(const auto& f:tracked){bool exists=false;string h=hashFile(f,exists);out<<f<<"|"<<(exists?"PRESENT":"MISSING")<<"|"<<h<<"\n";}out.close();logger.logEvent(actor,role,"INTEGRITY_BASELINE","SUCCESS");cout<<"Baseline created: integrity_baseline.txt\nExisting file checksums recorded. This is not a cryptographic signature.\n";}
void AuditIntegrityEngine::showBaseline()const{ifstream in("integrity_baseline.txt");if(!in){cout<<"No baseline found. Create one first.\n";return;}cout<<"\n===== INTEGRITY BASELINE =====\n"<<in.rdbuf();}
void AuditIntegrityEngine::verifyBaseline(const string& actor,const string& role){ifstream in("integrity_baseline.txt");if(!in){cout<<"Create a baseline first.\n";return;}string line;int checked=0,changed=0,missing=0;ofstream report("integrity_verification_report.txt",ios::trunc);if(!report){cout<<"Could not create verification report.\n";return;}report<<"VIGILX INTEGRITY VERIFICATION\nFNV-1a is a non-cryptographic educational checksum.\n\n";while(getline(in,line)){if(line.empty()||line.find("VIGILX ")==0||line.find("Algorithm:")==0)continue;auto p1=line.find('|'),p2=line.find('|',p1+1);if(p1==string::npos||p2==string::npos)continue;string name=line.substr(0,p1),status=line.substr(p1+1,p2-p1-1),old=line.substr(p2+1);bool exists=false;string now=hashFile(name,exists);string result;if(status=="MISSING"&&!exists)result="UNCHANGED_MISSING_AT_BASELINE";else if(status=="MISSING"&&exists)result="NEW_FILE_PRESENT";else if(!exists){result="MISSING_NOW";++missing;++changed;}else if(old!=now){result="CHANGED";++changed;}else result="UNCHANGED";++checked;report<<name<<" | baseline="<<status<<" | current="<<(exists?"PRESENT":"MISSING")<<" | "<<result<<"\n";}report<<"\nFiles checked: "<<checked<<"\nChanged/new/missing indicators: "<<changed<<"\n";report.close();logger.logEvent(actor,role,"INTEGRITY_VERIFY",changed?"REVIEW_REQUIRED_"+to_string(changed):"SUCCESS_NO_CHANGES");cout<<"Verification complete. Indicators requiring review: "<<changed<<"\nReport: integrity_verification_report.txt\n";}
void AuditIntegrityEngine::runMenu(const string& username,const string& role){if(role!="Admin"&&role!="SecurityAnalyst"){cout<<"Access denied.\n";return;}int c;do{cout<<"\n===== AUDIT TRAIL & INTEGRITY =====\n1. Create/Replace Local Baseline\n2. Verify Files Against Baseline\n3. View Baseline\n0. Return\nChoice: ";if(!(cin>>c)){cin.clear();cin.ignore(100000,'\n');cout<<"Invalid input.\n";continue;}cin.ignore(100000,'\n');switch(c){case 1:createBaseline(username,role);break;case 2:verifyBaseline(username,role);break;case 3:showBaseline();break;case 0:break;default:cout<<"Invalid choice.\n";}}while(c!=0);}
